instance [Group G] : SubgroupClass₁ (Subgroup₁ G) G :=
{ (inferInstance : SubmonoidClass₁ (Subgroup₁ G) G) with
  inv_mem := Subgroup₁.inv_mem }

theorem C10_S03_28{x : X} {F : Filter X} {G : Filter Y} (H : ClusterPt x F) {f : X → Y}
    (hfx : ContinuousAt f x) (hf : Tendsto f F G) : ClusterPt (f x) G :=
  ClusterPt.map H hfx hf

theorem aux {X Y A : Type*} [TopologicalSpace X] {c : A → X}
      {f : A → Y} {x : X} {F : Filter Y}
      (h : Tendsto f (comap c (𝓝 x)) F) {V' : Set Y} (V'_in : V' ∈ F) :
    ∃ V ∈ 𝓝 x, IsOpen V ∧ c ⁻¹' V ⊆ f ⁻¹' V' := by
  simpa [and_assoc] using ((nhds_basis_opens' x).comap c).tendsto_left_iff.mp h V' V'_in

theorem C10_S03_18{Z : Type*} (f : X → Y) (T_X : TopologicalSpace X) (T_Z : TopologicalSpace Z)
      (g : Y → Z) :
    @Continuous Y Z (TopologicalSpace.coinduced f T_X) T_Z g ↔
      @Continuous X Z T_X T_Z (g ∘ f) := by
  rw [continuous_iff_coinduced_le, coinduced_compose, continuous_iff_coinduced_le]

private lemma pnat_to_nat_prop2 {P : ℕ+ → ℕ+ → Prop} :
  (∀ m n : ℕ+, P m n) ↔ (∀ m n : ℕ, P m.succPNat n.succPNat) :=
  by rw [pnat_to_nat_prop]; refine forall_congr' (λ m ↦ ?_); rw [pnat_to_nat_prop]

private lemma pnat_to_nat_prop {P : ℕ+ → Prop} :
  (∀ n : ℕ+, P n) ↔ (∀ n : ℕ, P n.succPNat) :=
  ⟨λ h n ↦ h n.succPNat, λ h n ↦ by rw [← PNat.succPNat_natPred n]; exact h _⟩

problem usa2001_p1 : IsLeast possible_num_colors min_colors := by
  -- Informal solution from
  -- https://artofproblemsolving.com/wiki/index.php/2001_USAMO_Problems/Problem_1
  constructor
  · rw [Set.mem_def, possible_num_colors, Set.setOf_app_iff]
    let f : Fin 8 → Finset (Fin 23)
        | 0 => {1, 2, 3, 4, 5, 6}
        | 1 => {1, 7, 8, 9, 10, 11}
        | 2 => {1, 12, 13, 14, 15, 16}
        | 3 => {2, 7, 12, 17, 18, 19}
        | 4 => {3, 8, 13, 17, 20, 21}
        | 5 => {4, 9, 14, 17, 22, 23}
        | 6 => {5, 10, 15, 18, 20, 22}
        | 7 => {6, 11, 16, 19, 21, 23}
    use f
    constructor
    · intro i
      fin_cases i <;> simp (config := {decide := true}) [f]
    · intro x y i j hij hx hy
      sorry
  · sorry
